// Common的原typed recipe独占实际预留、消费和释放；本域不向儿童或接手者铸造第二份食物。
#include "child_care_relief_resources.hpp"
#include <charconv>
#include <tuple>
namespace hanmo::resident {namespace {
// 真接受实例必须已分配且具有本域原payload；不接受伪造前缀、未来ID或别域合同。
bool allocated(const CommonStore& c,const StableId& id){const StableId prefix="family_care_relief:";if(id.rfind(prefix,0)!=0)return false;const auto raw=id.substr(prefix.size());Integer value=0;const auto parsed=std::from_chars(raw.data(),raw.data()+raw.size(),value);return parsed.ec==std::errc{}&&parsed.ptr==raw.data()+raw.size()&&value>0&&value<c.state().next_instance_id&&raw==std::to_string(value);}
Outcome<Integer> total(const ChildCareReliefSource& source){const auto& t=source.terms;if(t.food_per_period<1||t.food_per_period>10000||t.prepaid_periods<1||t.prepaid_periods>360)return {false,0,common_failure("InvalidChildCareReliefSupplyAmount").error};return {true,t.food_per_period*t.prepaid_periods,{}};}
Status inventory(const CommonStore& c,const ChildCareReliefSource& source){const auto* provider=c.actor(source.provider_actor_id);const auto* bag=c.inventory(source.terms.source_inventory_id);const Owner owner{Owner::Kind::actor,source.provider_actor_id,{}};return provider&&bag&&provider->inventory_id==bag->id&&!bag->owner.extra&&owner_equal(bag->owner,owner)&&c.item_definition(source.terms.food_item_id)?common_success():common_failure("ChildCareReliefOwnInventoryRequired");}
}
bool child_care_relief_reservation_exists(const CommonStore& c,const ChildCareReliefState& s,const ReservationRef& ref){if(ref.kind!=ReservationRef::Kind::contract||!allocated(c,ref.id))return false;const auto* row=s.agreements.find(ref.id);const auto* h=c.state().facts.find(ref.id);return row&&row->kind=="family_care_relief_accepted"&&h&&h->id==ref.id&&h->kind==row->kind&&h->domain=="family_care_relief";}
Outcome<ChildCareReliefSupplyQuote> preview_child_care_relief_supply(const CommonStore& c,const ChildCareReliefSource& source){
    auto valid=inventory(c,source);if(!valid.ok)return {false,{},valid.error};auto amount=total(source);if(!amount.ok)return {false,{},amount.error};
    const auto* provider=c.actor(source.provider_actor_id);if(!provider->alive||!provider->available||!provider->action_id.empty())return {false,{},common_failure("ChildCareReliefProviderUnavailable").error};auto where=c.resolved_location(provider->id);if(!where.ok)return {false,{},where.error};const auto* at=std::get_if<SettlementLocation>(&where.value);if(!at||at->place_id!=source.terms.place_id)return {false,{},common_failure("ChildCareReliefNotAtPlace").error};
    const auto* bag=c.inventory(source.terms.source_inventory_id);const Owner owner{Owner::Kind::actor,provider->id,{}};
    for(const auto& lot:bag->lots)if(lot.item_id==source.terms.food_item_id&&lot.reserved_by.empty()&&owner_equal(lot.owner,owner)&&(lot.extra||lot.owner.extra))return {false,{},common_failure("UnsupportedChildCareReliefLot",lot.id).error};
    auto available=c.count(bag->id,source.terms.food_item_id,{owner});if(!available.ok)return {false,{},available.error};if(available.value<amount.value)return {false,{},common_failure("InsufficientChildCareReliefFood").error};
    return {true,{c.state().identity,source,amount.value,bag->revision,available.value},{}};
}
Status validate_child_care_relief_reservation(const CommonStore& c,const ChildCareReliefState& state,const StableId& accepted,Integer remaining){
    const ReservationRef reservation{ReservationRef::Kind::contract,accepted};if(!child_care_relief_reservation_exists(c,state,reservation)||!c.reservation_exists(reservation))return common_failure("ChildCareReliefReservationOwnerRequired",accepted);
    const auto& source=state.agreements.find(accepted)->source;auto valid=inventory(c,source);if(!valid.ok)return valid;auto amount=total(source);if(!amount.ok)return {false,{},amount.error};if(remaining<0||remaining>amount.value)return common_failure("InvalidChildCareReliefRemainingFood");
    for(const auto& row:c.state().wallets.rows())for(const auto& hold:row.second.reserved)if(hold.action_id==reservation)return common_failure("UnexpectedChildCareReliefMoneyReservation",row.first);
    const Owner owner{Owner::Kind::actor,source.provider_actor_id,{}};Integer actual=0;
    for(const auto& row:c.state().inventories.rows())for(const auto& lot:row.second.lots)if(lot.reserved_by==reservation){if(row.first!=source.terms.source_inventory_id||lot.item_id!=source.terms.food_item_id||lot.quantity<=0||lot.extra||lot.owner.extra||!owner_equal(lot.owner,owner)||lot.quantity>amount.value-actual)return common_failure("UnexpectedChildCareReliefReservation",lot.id);actual+=lot.quantity;}
    return actual==remaining?common_success():common_failure("ChildCareReliefReservationAmountMismatch",accepted);
}
Outcome<ResourceRecipe> reserve_child_care_relief_recipe(const CommonStore& c,const ChildCareReliefState& state,const ChildCareReliefSupplyQuote& quote,const StableId& accepted){
    const auto& now=c.state().identity;if(std::tie(now.world_id,now.execution_epoch,now.revision,now.tick)!=std::tie(quote.identity.world_id,quote.identity.execution_epoch,quote.identity.revision,quote.identity.tick))return {false,{},common_failure("StaleChildCareReliefSupplyQuote").error};
    const auto* row=state.agreements.find(accepted);if(!row||!child_care_relief_source_equal(row->source,quote.source)||row->reserved_food!=quote.quantity)return {false,{},common_failure("ChildCareReliefSupplySourceMismatch").error};
    auto fresh=preview_child_care_relief_supply(c,quote.source);if(!fresh.ok)return {false,{},fresh.error};if(fresh.value.quantity!=quote.quantity||fresh.value.inventory_revision!=quote.inventory_revision||fresh.value.available_before!=quote.available_before)return {false,{},common_failure("ChildCareReliefSupplyChanged").error};
    auto valid=validate_child_care_relief_reservation(c,state,accepted,0);if(!valid.ok)return {false,{},valid.error};ResourceRecipe recipe;recipe.operations.push_back(ReserveLots{quote.source.terms.source_inventory_id,quote.source.terms.food_item_id,quote.quantity,{{Owner::Kind::actor,quote.source.provider_actor_id,{}}},{ReservationRef::Kind::contract,accepted}});return {true,std::move(recipe),{}};
}
Outcome<ResourceRecipe> consume_child_care_relief_recipe(const CommonStore& c,const ChildCareReliefState& state,const StableId& accepted,Integer remaining,Integer consumed){auto valid=validate_child_care_relief_reservation(c,state,accepted,remaining);if(!valid.ok)return {false,{},valid.error};const auto& source=state.agreements.find(accepted)->source;if(consumed!=source.terms.food_per_period||consumed>remaining)return {false,{},common_failure("InvalidChildCareReliefConsumption").error};ResourceRecipe recipe;recipe.operations.push_back(ConsumeLots{source.terms.source_inventory_id,source.terms.food_item_id,consumed,{{Owner::Kind::actor,source.provider_actor_id,{}}},{ReservationRef::Kind::contract,accepted}});return {true,std::move(recipe),{}};}
Outcome<ResourceRecipe> release_child_care_relief_recipe(const CommonStore& c,const ChildCareReliefState& state,const StableId& accepted,Integer remaining){auto valid=validate_child_care_relief_reservation(c,state,accepted,remaining);if(!valid.ok)return {false,{},valid.error};ResourceRecipe recipe;recipe.operations.push_back(ReleaseReservationResources{{ReservationRef::Kind::contract,accepted}});return {true,std::move(recipe),{}};}
}
